import { createChart, removeChart, getViewGroup } from '../../../core/utHelper';
import { EChartsType } from '../../../../../src/echarts';
import Element from 'zrender/src/Element';
import { MatrixLabelFormatterParams } from '../../../../../src/coord/matrix/MatrixModel';

function getCellTexts(chart: EChartsType): string[] {
    const texts: string[] = [];
    getViewGroup(chart, 'matrix').traverse(function (el: Element) {
        const textContent = el.getTextContent();
        if (textContent) {
            texts.push(textContent.style.text as string);
        }
    });
    return texts;
}

describe('matrix_label_formatter', function () {

    let chart: EChartsType;

    beforeEach(function () {
        chart = createChart();
    });

    afterEach(function () {
        removeChart(chart);
    });

    it('should apply string template formatter on x/y dimension labels', function () {
        chart.setOption({
            matrix: {
                x: {
                    data: ['A', 'B'],
                    label: { formatter: 'Col: {name}' }
                },
                y: {
                    data: ['X', 'Y'],
                    label: { formatter: 'Row: {name}' }
                }
            }
        });
        // x header cells come first, then y header cells.
        expect(getCellTexts(chart)).toEqual(['Col: A', 'Col: B', 'Row: X', 'Row: Y']);
    });

    it('should apply callback formatter and pass name/value/coord', function () {
        const received: MatrixLabelFormatterParams[] = [];
        chart.setOption({
            matrix: {
                x: {
                    data: ['A', 'B'],
                    label: {
                        formatter: function (params: MatrixLabelFormatterParams) {
                            received.push(params);
                            return '<' + params.name + '>';
                        }
                    }
                },
                y: { data: ['X'] },
                body: {
                    data: [{ coord: ['A', 'X'], value: 'v1' }],
                    label: {
                        formatter: function (params: MatrixLabelFormatterParams) {
                            received.push(params);
                            return params.value + '!';
                        }
                    }
                }
            }
        });

        expect(getCellTexts(chart)).toEqual(['<A>', '<B>', 'X', 'v1!']);

        expect(received.length).toEqual(3);
        expect(received[0].componentType).toEqual('matrix');
        expect(received[0].componentIndex).toEqual(0);
        expect(received[0].name).toEqual('A');
        expect(received[0].value).toEqual('A');
        // x header cells live on the negative y locator (header area).
        expect(received[0].coord).toEqual([0, -1]);
        expect(received[1].coord).toEqual([1, -1]);
        // The body cell.
        expect(received[2].name).toEqual('v1');
        expect(received[2].coord).toEqual([0, 0]);
    });

    it('should let cell level formatter override the dimension level one', function () {
        chart.setOption({
            matrix: {
                x: {
                    data: ['A', { value: 'B', label: { formatter: 'cell-{name}' } }],
                    label: { formatter: 'dim-{name}' }
                },
                y: { data: ['X'] }
            }
        });
        expect(getCellTexts(chart)).toEqual(['dim-A', 'cell-B', 'X']);
    });

    it('should keep the raw text when no formatter is declared', function () {
        chart.setOption({
            matrix: {
                x: { data: ['A'] },
                y: { data: ['X'] }
            }
        });
        expect(getCellTexts(chart)).toEqual(['A', 'X']);
    });

});
```

Verified facts backing the assertions (measured on the current tree with a throwaway probe):
* traversal order of the matrix view group is x-header cells, then y-header cells, then
  body/corner cells;
* locators: x headers `[0,-1] [1,-1]`, y headers `[-1,0] [-1,1]`, body `[0,0]`;
* `el.getTextContent()` (zrender `Element#getTextContent`,
  `node_modules/zrender/src/Element.ts:1330`) is how the matrix label is attached — the label is
  *not* a child of the group, so `Group#traverse` alone would not find it.

Caveat for the third test: `matrix.x.data[i]` is `MatrixDimensionCellOption extends
MatrixBaseCellOption extends MatrixCellStyleOption`, so a per-cell `label` is legal — confirmed at
`MatrixModel.ts:135-136` and `:157-169`. If the per-cell override assertion turns out to be
affected by `Model` option-merging nuances, drop that single `it(...)` block; the first two are
